__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'adrianna.pienkowska@nokia.com, justyna.gacek@nokia.com'


class Chart:

    def __init__(self, workbook, worksheet, worksheet_data, is_nested):
        self.workbook = workbook
        self.worksheet = worksheet
        self.data = worksheet_data
        self.is_nested = is_nested

    def draw(self):
        """
        Draw appropriate charts depending on is_nested value.
        """
        if self.is_nested and self.data is not None:
            self._draw_nested_chart()
        else:
            self._draw_simple_chart()

    def _draw_nested_chart(self):
        """
        Draw charts using nested data.
        """
        row = 1
        for chart_list in self.data:
            chart = self.workbook.add_chart({'type': 'scatter', 'subtype': 'straight_with_markers'})
            chart.set_x_axis({'name': 'Timestamp', 'date_axis': True, 'num_format': 'mmm dd hh:mm:ss',
                              'num_font': {'rotation': -35}})
            chart.set_title({'name': [chart_list[0], 0, chart_list[2]]})
            for i in range(chart_list[2], chart_list[4]):
                series_list = chart_list[:2] + [i] + [chart_list[3]] + [i]
                chart.add_series({'categories': [chart_list[0], 2, 0, chart_list[3], 0],
                                  'values': series_list, 'name': [chart_list[0], 1, i]})
            self.worksheet.insert_chart(row, 5, chart, {'x_scale': 2, 'y_scale': 2})
            row += 35

    def _draw_simple_chart(self):
        """
        Draw one chart using simple data.
        """
        chart = self.workbook.add_chart({'type': 'scatter', 'subtype': 'straight_with_markers'})
        chart.set_x_axis({'name': 'Timestamp', 'date_axis': True, 'num_format': 'mmm dd hh:mm:ss',
                          'num_font': {'rotation': -35}})
        chart.set_title({'name': self.data[0]})
        for i in range(self.data[2], self.data[4]):
            names_list = [self.data[0], 1, i]
            series_list = self.data[:2] + [i] + [self.data[3]] + [i]
            categories_list = [self.data[0], 2, 0, self.data[3], 0]
            chart.add_series({'categories': categories_list, 'values': series_list, 'name': names_list})
        self.worksheet.insert_chart(1, 5, chart, {'x_scale': 2, 'y_scale': 2})
